use std::{env,fs};use native_browser::{Browser,render_png};fn main(){let a:Vec<_>=env::args().collect();if a.len()<2{eprintln!("usage: native-browser <file|html> [--headless output.png]");return}let s=fs::read_to_string(&a[1]).unwrap_or_else(|_|a[1].clone());if a.get(2).map(String::as_str)==Some("--headless"){render_png(&s,a.get(3).map(String::as_str).unwrap_or("output.png"),800,600).unwrap()}else{println!("native browser loaded {} display items",Browser::from_html(&s,800).display_list.items.len())}}
